from itertools import permutations

NORMALS = [(0, 0, 1), (0, 0, -1), (1, 0, 0), (-1, 0, 0), (0, 1, 0), (0, -1, 0)]

def det(a, b, c):
    return (a[0] * (b[1] * c[2] - b[2] * c[1]) - a[1] * (b[0] * c[2] - b[2] * c[0])
            + a[2] * (b[0] * c[1] - b[1] * c[0]))

def shows(cube, view):
    # view = (top, left, right) as drawn: three mutually adjacent faces, clockwise order top -> right -> left
    t, l, r = (cube[f] for f in view)
    return det(t, l, r) == 1

def opposite_by_enumeration(labels, views, target):
    found = set()
    for perm in permutations(NORMALS):
        cube = dict(zip(labels, perm))
        if all(shows(cube, v) for v in views):
            opp = [f for f in labels if cube[f] == tuple(-x for x in cube[target])][0]
            found.add(opp)
    return found

def common_face_rule(v1, v2):
    """Views are (top, left, right). A face in the same slot of both views: the other slots pair as opposites."""
    pairs = {}
    for i in range(3):
        if v1[i] == v2[i]:
            for j in range(3):
                if j != i:
                    pairs[v1[j]] = v2[j]
                    pairs[v2[j]] = v1[j]
            return pairs
    return None

def check(labels, v1, v2, target, options, answer):
    pairs = common_face_rule(v1, v2)
    got = pairs[target]
    assert got == options[answer], (got, options[answer])
    assert [k for k, val in options.items() if val == got] == [answer]
    # independent check: every cube consistent with both views has the same opposite face
    assert opposite_by_enumeration(labels, [v1, v2], target) == {got}

