# boundary: the common face must sit in the same position. Build a real cube, take views where the
# common face is in different positions, and show position-pairing then gives false opposites.
cube = dict(zip([1, 2, 3, 4, 5, 6], NORMALS))      # 1-2, 3-4, 5-6 opposite
views = [v for v in permutations(cube, 3) if shows(cube, v)]
same = [(a, b) for a in views for b in views if a != b and any(a[i] == b[i] for i in range(3))]
