for a, b in same:     # rule holds whenever exactly one face is shared in the same slot
    if len(set(a) & set(b)) == 1:
        assert all(true_opp(x, y) for x, y in common_face_rule(a, b).items())
naive_wrong = 0
for a, b in moved:
    pairs = [(a[i], b[i]) for i in range(3) if a[i] not in b]
    if not all(true_opp(x, y) for x, y in pairs):
        naive_wrong += 1
