def adjacency_elimination(labels, views):
    adj = {f: set() for f in labels}
    for v in views:
        for a in v:
            adj[a] |= set(v) - {a}
    opp = {}
    changed = True
    while changed:
        changed = False
        for f in labels:
            if f in opp:
                continue
            cand = set(labels) - {f} - adj[f] - set(opp)
            if len(cand) == 1:
                g = cand.pop()
                opp[f], opp[g] = g, f
                changed = True
    return opp

def check(labels, views, target, options, answer):
    opp = adjacency_elimination(labels, views)
    got = opp[target]
    assert got == options[answer], (got, options[answer])
    assert [k for k, val in options.items() if val == got] == [answer]
    assert opposite_by_enumeration(labels, views, target) == {got}

