from itertools import permutations

NORMALS = [(0, 0, 1), (0, 0, -1), (1, 0, 0), (-1, 0, 0), (0, 1, 0), (0, -1, 0)]

def det(a, b, c):
    return (a[0] * (b[1] * c[2] - b[2] * c[1]) - a[1] * (b[0] * c[2] - b[2] * c[0])
            + a[2] * (b[0] * c[1] - b[1] * c[0]))

def shows(cube, view):
    # view = (top, left, right) as drawn: three mutually adjacent faces, clockwise order top -> right -> left
    t, l, r = (cube[f] for f in view)
    return det(t, l, r) == 1

def opposite_by_enumeration(labels, views, target):
    found = set()
    for perm in permutations(NORMALS):
        cube = dict(zip(labels, perm))
        if all(shows(cube, v) for v in views):
            opp = [f for f in labels if cube[f] == tuple(-x for x in cube[target])][0]
            found.add(opp)
    return found

def ring_around(common, views):
    """Views share `common` on top. Each view gives (left, right) = two consecutive ring faces in clockwise order.
    Return the 4-face ring (as a cyclic list) consistent with every view."""
    sides = sorted({f for v in views for f in v if f != common})
    rings = []
    for p in permutations(sides):
        if p[0] != sides[0]:
            continue
        nxt = {p[i]: p[(i + 1) % 4] for i in range(4)}
        if all(nxt[v[1]] == v[2] for v in views):
            rings.append(p)
    return rings

def check(labels, views, target, options, answer):
    rings = ring_around(views[0][0], views)
    assert len(rings) == 1, rings
    ring = rings[0]
    got = ring[(ring.index(target) + 2) % 4]
    assert got == options[answer], (got, options[answer])
    assert [k for k, val in options.items() if val == got] == [answer]
    assert opposite_by_enumeration(labels, views, target) == {got}

