def fold(net):
    """net: {(row, col): label}. Roll a cube across the net; return label -> outward normal."""
    start = next(iter(sorted(net)))
    frame = {start: ((0, 0, -1), (1, 0, 0), (0, 1, 0))}   # (normal, right, down)
    stack = [start]
    neg = lambda v: tuple(-x for x in v)
    while stack:
        cell = stack.pop()
        n, r, d = frame[cell]
        for (dr, dc), new in (((0, 1), (r, neg(n), d)), ((0, -1), (neg(r), n, d)),
                              ((1, 0), (d, r, neg(n))), ((-1, 0), (neg(d), r, n))):
            nb = (cell[0] + dr, cell[1] + dc)
            if nb in net and nb not in frame:
                frame[nb] = new
                stack.append(nb)
    normals = {net[c]: frame[c][0] for c in net}
    assert len(set(normals.values())) == 6, "not a valid cube net"
    return normals

def opposite(net, target):
    nm = fold(net)
    return [f for f in nm if nm[f] == tuple(-x for x in nm[target])][0]

def straight_line_rule(net, target):
    """Two faces in the same row or column with exactly one face between them (all three present) are opposite."""
    pos = {v: k for k, v in net.items()}
    r, c = pos[target]
    for dr, dc in ((0, 2), (0, -2), (2, 0), (-2, 0)):
        mid, far = (r + dr // 2, c + dc // 2), (r + dr, c + dc)
        if mid in net and far in net:
            return net[far]
    return None

