import random
from collections import Counter
from itertools import product

def formula(n):
    return {3: 8, 2: 12 * (n - 2), 1: 6 * (n - 2) ** 2, 0: (n - 2) ** 3}

def brute(n):
    c = Counter(sum(x in (0, n - 1) for x in p) for p in product(range(n), repeat=3))
    return {k: c.get(k, 0) for k in range(4)}

def by_axes(n):
    # each coordinate is a painted layer (2 choices) or an inner layer (n - 2 choices)
    one = {1: 2, 0: n - 2}
    out = Counter()
    for a, b, c in product(one, repeat=3):
        out[a + b + c] += one[a] * one[b] * one[c]
    return {k: out.get(k, 0) for k in range(4)}

for n in range(2, 13):
    assert brute(n) == formula(n), n
random.seed(0)
cases = 0
for _ in range(1000):
    n = random.randint(2, 500)
    f = formula(n)
    assert f == by_axes(n)
    assert sum(f.values()) == n ** 3
    cases += 1
print(f"CASES={cases}")
# boundary n >= 2: at n = 2 every small cube is a corner; at n = 1 the formula breaks (one cube, 6 faces painted)
assert formula(2) == brute(2) == {3: 8, 2: 0, 1: 0, 0: 0}
assert formula(1)[2] == -12 and formula(1)[3] == 8   # negative count, 8 corners from 1 cube: formula invalid
print("BOUNDARY_OK")
